me": "Metal Storage Cabinet", "price": 5999, "category": "Furniture & Office Equipment", "image": "/images/products/furniture-office/furniture-office-19-01.jpg", "rating": 4.7, "condition": "New"}, {"key": "furniture-and-office-equipment:20", "name": "3-Tier Utility Cart", "price": 1999, "category": "Furniture & Office Equipment", "image": "/images/products/furniture-office/furniture-office-20-01.jpg", "rating": 4.5, "condition": "New"}, {"key": "furniture-and-office-equipment:21", "name": "Office Laptop", "price": 24999, "category": "Furniture & Office Equipment", "image": "/images/products/furniture-office/furniture-office-21-01.jpg", "rating": 4.3, "condition": "New with tags"}, {"key": "furniture-and-office-equipment:22", "name": "Desktop Computer Set", "price": 29999, "category": "Furniture & Office Equipment", "image": "/images/products/furniture-office/furniture-office-22-01.jpg", "rating": 4.8, "condition": "New"}, {"key": "furniture-and-office-equipment:23", "name": "Color Inkjet Printer", "price": 7999, "category": "Furniture & Office Equipment", "image": "/images/products/furniture-office/furniture-office-23-01.jpg", "rating": 4.6, "condition": "New"}, {"key": "furniture-and-office-equipment:24", "name": "Multifunction Photocopier", "price": 39999, "category": "Furniture & Office Equipment", "image": "/images/products/furniture-office/furniture-office-24-01.jpg", "rating": 4.4, "condition": "New with tags"}, {"key": "furniture-and-office-equipment:25", "name": "24-Inch Office Monitor", "price": 8999, "category": "Furniture & Office Equipment", "image": "/images/products/furniture-office/furniture-office-25-01.jpg", "rating": 4.9, "condition": "New"}, {"key": "furniture-and-office-equipment:26", "name": "Keyboard & Mouse Combo", "price": 1499, "category": "Furniture & Office Equipment", "image": "/images/products/furniture-office/furniture-office-26-01.jpg", "rating": 4.7, "condition": "New"}, {"key": "furniture-and-office-equipment:27", "name": "Backup UP